typedef struct o_Token {
    o_TokType tag;
    orbit_string text;
    orbit_int line;
    orbit_int col;
    orbit_int start;
    orbit_int len;
} o_Token;
#define o_Token(...) (o_Token*)orbit_model_o_Token_create(arena, __VA_ARGS__)
static inline o_Token* orbit_model_o_Token_create(OrbitArena* arena_, o_TokType tag, orbit_string text, orbit_int line, orbit_int col, orbit_int start, orbit_int len) {
    o_Token* m = (o_Token*)orbit_alloc(arena_, sizeof(o_Token));
    m->tag = tag;
    m->text = text;
    m->line = line;
    m->col = col;
    m->start = start;
    m->len = len;
    return m;
}

